import re
from collections import Counter

def word_frequency(text: str) -> dict[str, int]:
    """
    Calculates the frequency of each word in a given text string.

    Args:
        text: The input string.

    Returns:
        A dictionary where keys are the words (in lowercase) and values 
        are their frequencies. Returns an empty dictionary for an empty string.
    """
    if not text:
        return {}

    # Convert to lowercase and split into words. 
    # Using re.findall to robustly extract sequences of word characters.
    words = re.findall(r'\b\w+\b', text.lower())

    # Use Counter to efficiently count word frequencies
    return dict(Counter(words))

if __name__ == '__main__':
    # Test cases
    print(f"Test 1: {word_frequency('Hello world, hello Python!')}")
    # Expected: {'hello': 2, 'world': 1, 'python': 1}

