def compute_gcd(a: int, b: int) -> int:
    """
    Computes the greatest common divisor (GCD) of two integers a and b.

    If one of them is 0, the result is the other one.
    """
    # Handle the case where one or both are zero
    if a == 0:
        return abs(b)
    if b == 0:
        return abs(a)

    # Use the Euclidean algorithm
    # The GCD is always non-negative, so we work with absolute values
    a = abs(a)
    b = abs(b)

    while b:
        a, b = b, a % b
    return a
