        return []

    # Check if all rows in both matrices have the same number of columns
    for row in a:
        if len(row) != cols_a:
            return []
    for row in b:
        if len(row) != cols_b:
            return []

    # Perform addition
    result = []
    for i in range(rows_a):
        new_row = []
        for j in range(cols_a):
            new_row.append(a[i][j] + b[i][j])
        result.append(new_row)

