def min_max_normalize(nums: list[float]) -> list[float]:
    """
    Escala linealmente los números de la lista nums al rango de 0.0 a 1.0,
    redondea cada resultado a 2 decimales y los devuelve en el orden original.
    Si todos los valores son iguales, cada elemento del resultado es 0.0; 
    si nums está vacía, devuelve una lista vacía.
    """
    if not nums:
        return []

    min_val = min(nums)
    max_val = max(nums)

    if max_val == min_val:
        # Si todos los valores son iguales, cada elemento del resultado es 0.0
        return [0.0] * len(nums)
    else:
        # Fórmula de normalización Min-Max: (x - min) / (max - min)
        range_val = max_val - min_val
        normalized_nums = [round((x - min_val) / range_val, 2) for x in nums]
        return normalized_nums

def parse_kv_pairs(text: str) -> dict[str, str]:
    """
    Parses the string text into a dictionary of key-value pairs.

    The string contains 'key=value' pairs separated by semicolons (;).
    Whitespace around each pair, key, and value is removed.
    Pairs without '=' are ignored.

    Args:
        text: The input string containing key=value pairs.

    Returns:
        A dictionary mapping keys to their values.
    """
    if not text:
        return {}

    result = {}
    pairs = text.split(';')

    for pair in pairs:
        pair = pair.strip()
        if not pair:
            continue

        if '=' in pair:
            try:
                key, value = pair.split('=', 1)
                key = key.strip()
                value = value.strip()
                if key:  # Ensure the key is not empty after stripping
                    result[key] = value
            except ValueError:
                # Should not happen if '=' is checked, but good practice
                continue

    return result

