def count_climbing_steps(n: int) -> int:
    """
    n ধাপের একটি সিঁড়ি বেয়ে ওঠার মোট ভিন্ন উপায়ের সংখ্যা ফেরত দেয়, যেখানে প্রতিটী পদখেপে ১, ২ বা ৩ ধাপ ওঠা যায়।
    পদক্শেপের ক্রম আলাদা হলে তা ভিন্ন উপায় হিশেবে গণ্য হয়।
    n-এর মান 0 হলে ফলাফল 1, আর n ঋণাত্মক হলে ফলাফল 0।
    """
    if n < 0:
        return 0
    if n == 0:
        return 1
    if n == 1:
        return 1  # (1)
    if n == 2:
        return 2  # (1, 1), (2)
    if n == 3:
        return 4  # (1, 1, 1), (1, 2), (2, 1), (3)

    # Dynamic Programming approach
    # dp[i] will store the number of ways to reach step i
    dp = [0] * (n + 1)
    dp[0] = 1
    dp[1] = 1
    dp[2] = 2

    for i in range(3, n + 1):
        # To reach step i, we can come from step i-1 (by taking 1 step),
        # step i-2 (by taking 2 steps), or step i-3 (by taking 3 steps).
        dp[i] = dp[i-1] + dp[i-2] + dp[i-3]

    return dp[n]
