def longest_bitonic_length(nums: list[int]) -> int:
    """
    Devuelve la longitud de la subsecuencia bitónica más larga de la lista de enteros nums.
    """
    n = len(nums)
    if n == 0:
        return 0

    # 1. Calcular la Longest Increasing Subsequence (LIS) terminando en cada índice i
    # lis[i] = longitud de la subsecuencia creciente más larga que termina en nums[i]
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if nums[i] > nums[j]:
                lis[i] = max(lis[i], lis[j] + 1)

    # 2. Calcular la Longest Decreasing Subsequence (LDS) comenzando en cada índice i
    # lds[i] = longitud de la subsecuencia decreciente más larga que comienza en nums[i]
    # Esto es equivalente a LIS en el array invertido, pero lo calculamos directamente
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(n - 1, i, -1):
            if nums[i] > nums[j]:
                lds[i] = max(lds[i], lds[j] + 1)

    # 3. Calcular la longitud bitónica más larga
    # La longitud de una subsecuencia bitónica con pico en i es lis[i] + lds[i] - 1
    # Restamos 1 porque nums[i] se cuenta dos veces (una vez en LIS y una vez en LDS).
    max_length = 0
    for i in range(n):
        current_length = lis[i] + lds[i] - 1
        max_length = max(max_length, current_length)

    return max_length

