from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    """
    Returns the minimum number of moves needed to go from 'S' to 'E' in grid,
    allowing at most one move through a wall cell ('#').
    """
    R = len(grid)
    C = len(grid[0])
    start = None
    end = None

    for r in range(R):
        for c in range(C):
            if grid[r][c] == 'S':
                start = (r, c)
            elif grid[r][c] == 'E':
                end = (r, c)

    if not start or not end:
        return -1  # Should not happen based on problem description

    # State: (row, col, wall_broken)
    # wall_broken: 0 if no wall has been broken yet, 1 if one wall has been broken.
    # We use BFS to find the shortest path.
    queue = deque([(start[0], start[1], 0, 0)])  # (r, c, wall_broken, distance)
    visited = set([(start[0], start[1], 0)])

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    while queue:
        r, c, broken, dist = queue.popleft()

        if (r, c) == end:
            return dist

        for dr, dc in directions:
            nr, nc = r + dr, c + dc

            if 0 <= nr < R and 0 <= nc < C:
                cell = grid[nr][nc]
                new_broken = broken

                if cell == '#':
                    if broken == 0:
                        # We can break the wall. This move costs 1.
                        new_broken = 1
                        # The state transition is (r, c, 0) -> (nr, nc, 1)
                        # The move itself is counted in 'dist + 1'
                        if (nr, nc, new_broken) not in visited:
                            visited.add((nr, nc, new_broken))
                            queue.append((nr, nc, new_broken, dist + 1))
                    # If broken == 1, we cannot enter another wall.
                    continue
                else: # cell is '.' or 'E' or 'S' (though S/E are only start/end)
                    # Normal move
                    if (nr, nc, broken) not in visited:
                        visited.add((nr, nc, broken))
                        queue.append((nr, nc, broken, dist + 1))

    return -1

