def matches_filter(expression: str, record: dict) -> bool:
    """
    Evalúa la expresión de filtro 'expression' para los valores del diccionario 'record' 
    y devuelve True si la expresión es verdadera y False en caso contrario.

    Args:
        expression: La expresión de filtro (string).
        record: El diccionario de datos.

    Returns:
        bool: El resultado de la evaluación de la expresión.

    Raises:
        ValueError: Si la expresión no es válida o usa un nombre no presente en record.
    """

    # 1. Define un entorno seguro para la evaluación
    # Solo permitimos nombres (variables) que son claves del record.
    allowed_names = list(record.keys())

    # Mapeo de operadores permitidos
    allowed_operators = {
        'and': operator.and_,
        'or': operator.or_,
        'not': operator.not_,
        '<': operator.lt,
        '<=': operator.le,
        '>': operator.gt,
        '>=': operator.ge,
        '==': operator.eq,
        '!=': operator.ne,
    }

    # 2. Función de sustitución segura para el AST
    def safe_eval(node):
        """
        Evalúa un nodo del AST de forma segura, sustituyendo nombres por valores de record.
        """
        if isinstance(node, ast.Expression):
            return safe_eval(node.body)

        elif isinstance(node, ast.Constant):
            # Literales (int, float, str, bool, None)
            return node.value

        elif isinstance(node, ast.Name):
            # Variables (deben ser claves de record)
            if node.id in record:
                return record[node.id]
            else:
                raise ValueError(f"Nombre '{node.id}' no es una clave válida en el registro.")

        elif isinstance(node, ast.BinOp):
            # Operadores binarios (>, <, ==, and, or, etc.)
            op_type = type(node.op)

            if isinstance(node.op, ast.Gt):
                return safe_eval(node.left) > safe_eval(node.right)
            elif isinstance(node.op, ast.GtE):
                return safe_eval(node.left) >= safe_eval(node.right)
            elif isinstance(node.op, ast.Lt):
                return safe_eval(node.left) < safe_eval(node.right)
            elif isinstance(node.op, ast.LtE):
                return safe_eval(node.left) <= safe_eval(node.right)
            elif isinstance(node.op, ast.Eq):
                return safe_eval(node.left) == safe_eval(node.right)
            elif isinstance(node.op, ast.NotEq):
                return safe_eval(node.left) != safe_eval(node.right)
            elif isinstance(node.op, ast.And):
                return safe_eval(node.left) and safe_eval(node.right)
            elif isinstance(node.op, ast.Or):
                return safe_eval(node.left) or safe_eval(node.right)
            else:
                raise ValueError

