def flatten_list(nested: list) -> list:
    """
    Receives a list nested, whose elements can themselves be arbitrarily nested lists, 
    and returns a single flat list containing all the elements that are not lists, 
    in their original left-to-right order.
    """
    flat_list = []
    for element in nested:
        if isinstance(element, list):
            flat_list.extend(flatten_list(element))
        else:
            flat_list.append(element)
    return flat_list

def binary_search(arr: list[int], target: int) -> int:
    """
    Searches for target in an ascending order sorted integer list arr and returns the index of target.
    If target is not present, returns -1.
    """
    low = 0
    high = len(arr) - 1

    while low <= high:
        mid = (low + high) // 2

        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1

    return -1

