    """
    Checks whether the integer list nums is monotonic, meaning that all values 
    in the list are either non-decreasing or non-increasing.
    An empty list is considered monotonic.
    """
    if len(nums) <= 1:
        return True

    is_increasing = True
    is_decreasing = True

    for i in range(len(nums) - 1):
