def boustrophedon_order(matrix: list[list[int]]) -> list[int]:
    """
    Reads all elements of the 2D list matrix row by row in an alternate direction 
    (boustrophedon order) and returns a flat list.
    """
    if not matrix:
        return []

    result = []
    for i, row in enumerate(matrix):
        # If the row index (i) is even (0, 2, 4, ...), read left to right
        if i % 2 == 0:
            result.extend(row)
        # If the row index (i) is odd (1, 3, 5, ...), read right to left
        else:
            result.extend(row[::-1])

    return result

