def count_climbing_steps(n: int) -> int:
    """
    Returns the total number of distinct ways to climb a staircase with n steps, 
    where each step can be 1, 2, or 3 steps.
    If n is 0, the result is 1, and if n is negative, the result is 0.
    """
    if n < 0:
        return 0
    if n == 0:
        return 1
    if n == 1:
        return 1  # (1)
    if n == 2:
        return 2  # (1, 1), (2)
    if n == 3:
        return 4  # (1, 1, 1), (1, 2), (2, 1), (3)

    # dp[i] will store the number of ways to reach step i
    dp = [0] * (n + 1)
    dp[0] = 1
    dp[1] = 1
    dp[2] = 2
    dp[3] = 4

    for i in range(4, n + 1):
        # To reach step i, the last step taken could be 1, 2, or 3 steps.
        # Ways to reach i = Ways to reach (i-1) + Ways to reach (i-2) + Ways to reach (i-3)
        dp[i] = dp[i-1] + dp[i-2] + dp[i-3]

    return dp[n]
