def digital_root_sequence(n: int) -> list[int]:
    """
    Returns a list of numbers obtained by repeatedly adding the digits of the integer n,
    until a single-digit number (digital root) is reached.
    """
    if n < 0:
        current_number = abs(n)
    else:
        current_number = n

    sequence = []

    def sum_digits(num: int) -> int:
        s = 0
        for digit in str(num):
            s += int(digit)
        return s

    while current_number >= 10:
        sequence.append(current_number)
        current_number = sum_digits(current_number)

    sequence.append(current_number)
    return sequence

