from datetime import datetime, timedelta

def add_business_days(start: str, n: int, holidays: list[str]) -> str:
    """
    Adds or subtracts n business days from a start date.

    A business day is defined as any day from Monday to Friday that is not in the holidays list.
    The start day is not counted.
    """
    if n == 0:
        return start

    start_date = datetime.strptime(start, "%Y-%m-%d")
    current_date = start_date
    days_to_add = n

    # Convert holidays list to a set of datetime objects for efficient lookup
    holiday_dates = set()
    for h_str in holidays:
        holiday_dates.add(datetime.strptime(h_str, "%Y-%m-%d").date())

    def is_business_day(date_obj: datetime.date) -> bool:
        # Monday is 0 and Sunday is 6
        weekday = date_obj.weekday()
        if weekday >= 5:  # Saturday (5) or Sunday (6)
            return False
        if date_obj.date() in holiday_dates:
            return False
        return True

    if n > 0:
        # Move forward
        while days_to_add > 0:
            current_date += timedelta(days=1)
            if is_business_day(current_date.date()):
                days_to_add -= 1
    else:
        # Move backward (n is negative)
        while days_to_add < 0:
            current_date -= timedelta(days=1)
            if is_business_day(current_date.date()):
                days_to_add += 1  # Increment towards 0

    return current_date.strftime("%Y-%m-%d")
