from collections import deque

def min_slides(grid: list[str]) -> int:
    R = len(grid)
    C = len(grid[0])

    start_pos = None
    exit_pos = None

    for r in range(R):
        for c in range(C):
            if grid[r][c] == 'S':
                start_pos = (r, c)
            elif grid[r][c] == 'E':
                exit_pos = (r, c)

    if not start_pos or not exit_pos:
        return -1  # Should not happen based on problem description

    # State: (row, col)
    queue = deque([(start_pos, 0)])
    visited = {start_pos}

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # Up, Down, Left, Right

    while queue:
        (r, c), moves = queue.popleft()

        if (r, c) == exit_pos:
            return moves

        for dr, dc in directions:
            # Check the first cell in the direction
            next_r_start = r + dr
            next_c_start = c + dc

            # A move is valid only if the first cell in that direction is not a wall.
            if 0 <= next_r_start < R and 0 <= next_c_start < C and grid[next_r_start][next_c_start] != '#':

                # Simulate the slide
                current_r, current_c = r, c
                while True:
                    next_r, next_c = current_r + dr, current_c + dc

                    # Stop if outside grid or hits a wall
                    if not (0 <= next_r < R and 0 <= next_c < C) or grid[next_r][next_c] == '#':
                        break

                    # Move one step
                    current_r, current_c = next_r, next_c

                end_pos = (current_r, current_c)

                if end_pos not in visited:
                    visited.add(end_pos)
                    queue.append((end_pos, moves + 1))

    return -1
