from collections import deque

def min_slides(grid: list[str]) -> int:
    R = len(grid)
    C = len(grid[0])

    start_pos = None
    exit_pos = None

    for r in range(R):
        for c in range(C):
            if grid[r][c] == 'S':
                start_pos = (r, c)
            elif grid[r][c] == 'E':
                exit_pos = (r, c)

    if not start_pos or not exit_pos:
        return -1 # Should not happen based on problem description

    # State: (row, col)
    queue = deque([(start_pos, 0)])
    visited = {start_pos}

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)] # Up, Down, Left, Right

    def get_slide_end(start_r, start_c, dr, dc):
        r, c = start_r, start_c
        while True:
            next_r, next_c = r + dr, c + dc

            # Check bounds
            if not (0 <= next_r < R and 0 <= next_c < C):
                break

            # Check for wall
            if grid[next_r][next_c] == '#':
                break

            # Move to the next cell
            r, c = next_r, next_c

        return r, c

    while queue:
        (r, c), moves = queue.popleft()

        if (r, c) == exit_pos:
            return moves

        # Try all 4 directions
        for dr, dc in directions:
            # Check if the first cell in that direction is not a wall
            next_r_initial, next_c_initial = r + dr, c + dc

            if 0 <= next_r_initial < R and 0 <= next_c_initial < C and grid[next_r_initial][next_c_initial] != '#':

                # Calculate the final stopping position after sliding
                end_r, end_c = get_slide_end(r, c, dr, dc)

                new_pos = (end_r, end_c)

                if new_pos not in visited:
                    visited.add(new_pos)
                    queue.append((new_pos, moves + 1))

    return -1
