def matrix_power_mod(matrix: list[list[int]], exp: int, mod: int) -> list[list[int]]:
    """
    Raises the square matrix 'matrix' to the non-negative integer power 'exp', 
    takes the modulo 'mod' of each entry in the result, and returns it.
    """
    n = len(matrix)
    if n == 0:
        return []

    def multiply_matrices(A: list[list[int]], B: list[list[int]], m: int) -> list[list[int]]:
        C = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                sum_val = 0
                for k in range(n):
                    # Perform multiplication and addition modulo m at each step to prevent overflow
                    term = (A[i][k] * B[k][j]) % m
                    sum_val = (sum_val + term) % m
                C[i][j] = sum_val
