def expand_template(template: str, values: dict[str, str]) -> str:
    """
    Fills in the placeholders in the string `template` with the values from the dictionary `values` 
    and returns the resulting string.
    """
    result = []
    i = 0
    n = len(template)

    while i < n:
        if template[i] == '{':
            # Check for {{
            if i + 1 < n and template[i+1] == '{':
                result.append('{')
                i += 2
                continue

            # Check for potential placeholder starting at i
            # Find the next '}'
            j = i + 1
            while j < n and template[j] != '}':
                j += 1

            if j < n and template[j] == '}':
                # Found a potential placeholder: {key}

                # Check for }} (which is handled by the {{ check if we consider it as a special case, 
                # but the rule says '}} produces a single }'. Let's handle it explicitly if it's not part of a key)
                if j + 1 < n and template[j+1] == '}':
                    # Found }}
                    result.append('}')
                    i += 2
                    continue

                # It's a potential placeholder {key}
                key = template[i+1:j]

                if key in values:
                    # Replace placeholder with value
                    result.append(values[key])
                    i = j + 1
                    continue
                else:
                    # Key not found, keep placeholder unchanged
                    # The placeholder is from i to j inclusive: {key}
                    result.append(template[i:j+1])
                    i = j + 1
                    continue

            # If no '}' follows, or if it's a standalone '{' not starting a valid placeholder structure
            # (i.e., it's not followed by a '}' that closes a key), it's preserved as a normal character.
            # This covers the case where '{' has no '}' after it.
            result.append(template[i])
            i += 1

        elif template[i] == '}':
            # Check for }}
            if i + 1 < n and template[i+1] == '}':
                result.append('}')
                i += 2
                continue
            else:
                # Standalone '}' not part of '}}'
                result.append(template[i])
                i += 1

        else:
            # Normal character
            result.append(template[i])
            i += 1

    return "".join(result)
