def run_bank_ops(balances: dict[str, int], ops: list[tuple]) -> tuple[dict[str, int], list[int]]:
    """
    Applies a list of banking operations to a copy of the balances dictionary.

    Args:
        balances: A dictionary mapping account names (str) to their balances (int).
        ops: A list of tuples representing the operations.

    Returns:
        A tuple containing (final_balances, failed), where final_balances is the 
        resulting dictionary and failed is a list of 0-based indices of failed operations.
    """
    current_balances = balances.copy()
    account_status = {account: True for account in balances}  # True means unfrozen
    failed_indices = []

    def is_frozen(account):
        return not account_status.get(account, False)

    for i, op in enumerate(ops):
        op_type = op[0]
        success = True

        try:
            if op_type == 'deposit':
                _, account, amount = op
                if account not in current_balances or amount <= 0:
                    success = False
                elif is_frozen(account):
                    success = False
                else:
                    current_balances[account] += amount

            elif op_type == 'withdraw':
                _, account, amount = op
                if account not in current_balances or amount <= 0:
                    success = False
                elif is_frozen(account):
                    success = False
                elif current_balances[account] < amount:
                    success = False
                else:
                    current_balances[account] -= amount

            elif op_type == 'transfer':
                _, source, target, amount = op
                if source not in current_balances or target not in current_balances:
                    success = False
                elif amount <= 0:
                    success = False
                elif source == target:
                    success = False
                elif is_frozen(source) or is_frozen(target):
                    success = False
                elif current_balances[source] < amount + 2:
                    success = False
                else:
                    # Deduct amount and fee
                    current_balances[source] -= (amount + 2)
                    current_balances[target] += amount

            elif op_type == 'freeze':
                _, account = op
                if account not in current_balances:
                    success = False
                else:
                    # Freezing an already frozen account succeeds but makes no change
                    account_status[account] = False

            elif op_type == 'unfreeze':
                _, account = op
                if account not in current_balances:
                    success = False
                else:
                    # Unfreezing an account that is not frozen succeeds but makes no change
                    account_status[account] = True

            else:
                # Operation name is not one of the five listed above
                success = False

        except Exception:
            # Catch any unexpected errors during operation execution
            success = False

        if not success:
            failed_indices.append(i)

    return current_balances, failed_indices

