def convert_base(number: str, from_base: int, to_base: int) -> str:
    """
    Converts the integer represented by the string number in from_base to to_base and returns it as a string.
    """
    if not (2 <= from_base <= 36 and 2 <= to_base <= 36):
        raise ValueError("Bases must be between 2 and 36.")

    if not number:
        raise ValueError("Input number string cannot be empty.")

    is_negative = False
    start_index = 0
    if number.startswith('-'):
        is_negative = True
        start_index = 1
        if len(number) == 1:  # Only "-"
            raise ValueError("Input number string cannot be just '-'")

    num_str = number[start_index:]

    if not num_str:
        # This case should be covered by the check above if number was just "-"
        raise ValueError("Input number string is invalid.")

    # Step 1: Convert from from_base to base 10 (integer)
    try:
        decimal_value = 0
        for char in num_str:
            if '0' <= char <= '9':
                value = int(char)
            elif 'a' <= char <= 'z':
                value = ord(char) - ord('a') + 10
            elif 'A' <= char <= 'Z':
                value = ord(char) - ord('A') + 10
            else:
                raise ValueError("Invalid character in number string.")

            if value >= from_base:
                raise ValueError("Invalid character for the given base.")

            decimal_value = decimal_value * from_base + value
    except ValueError as e:
        # Re-raise specific errors related to input validation
        if "Invalid character" in str(e) or "Invalid character for the given base" in str(e):
            raise ValueError("Invalid character or value for the given base.") from e
        raise e

    # Handle zero case immediately
    if decimal_value == 0:
        return "0"

    # Step 2: Convert from base 10 to to_base
    if is_negative:
        decimal_value = -decimal_value

    if to_base == 10:
        result = str(decimal_value)
    else:
        result_chars = []
        temp_value = abs(decimal_value)
        while temp_value > 0:
            remainder = temp_value % to_base
            if 0 <= remainder <= 9:
                char = str(remainder)
            else:
                # Map 10 -> 'a', 11 -> 'b', ..., 35 -> 'z'
                char = chr(ord('a') + remainder - 10)
            result_chars.append(char)
            temp_value //= to_base

        result = "".join(reversed(result_chars))

    # Step 3: Apply sign if necessary
    if is_negative and result != "0":
        return "-" + result
    else:
        return result
