from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    R = len(grid)
    C = len(grid[0])
    start = None
    end = None

    for r in range(R):
        for c in range(C):
            if grid[r][c] == 'S':
                start = (r, c)
            elif grid[r][c] == 'E':
                end = (r, c)

    if not start or not end:
        return -1  # Should not happen based on problem description

    def bfs(start_node, end_node, is_break_allowed):
        """
        Performs BFS to find the shortest path.
        If is_break_allowed is True, the path can pass through one wall cell.
        """
        # State: (row, col, breaks_used)
        # breaks_used: 0 if no wall has been passed through, 1 if one wall has been passed through.
        queue = deque([(start_node[0], start_node[1], 0, 0)])  # (r, c, breaks_used, distance)

        # Visited set: (r, c, breaks_used)
        visited = set([(start_node[0], start_node[1], 0)])

        while queue:
            r, c, breaks_used, dist = queue.popleft()

            if (r, c) == end_node:
                return dist

            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nr, nc = r + dr, c + dc

                if 0 <= nr < R and 0 <= nc < C:
                    cell_type = grid[nr][nc]

                    new_breaks_used = breaks_used
                    is_wall = (cell_type == '#')

                    if is_wall:
                        if breaks_used == 0:
                            new_breaks_used = 1
                        else:
                            # Cannot pass through a second wall
                            continue

                    # Check if the new state has been visited
                    new_state = (nr, nc, new_breaks_used)
                    if new_state not in visited:
                        visited.add(new_state)
                        queue.append((nr, nc, new_breaks_used, dist + 1))

        return -1

    # The problem implies a single path search where the "break" is the allowance to step onto one '#' cell.
    # We need to find the minimum distance across all possible paths that use 0 or 1 break.

    # Since the BFS above inherently handles the state (breaks_used), we just run it once.
    # The BFS finds the shortest path regardless of whether it uses 0 or 1 break, as long as the rules are followed.

    return bfs(start, end, True)

