import os

def serve_static(web_root: str, request_path: str) -> tuple[int, bytes]:
    """
    Looks for a file under the web_root directory corresponding to the URL path request_path 
    and returns a (status, body) tuple.

    Args:
        web_root: The root directory for serving static files.
        request_path: The URL path (e.g., "/css/site.css" or "/").

    Returns:
        A tuple (status, body) where status is an integer (200 or 404) 
        and body is the file content as bytes.
    """
    # Normalize the path: remove leading/trailing slashes and replace URL slashes with OS separators
    # Handle the root case "/" -> "index.html"
    if request_path == "/":
        file_name = "index.html"
        relative_path = ""
    else:
        # Remove leading slash and replace internal slashes with OS separator
        relative_path = request_path.lstrip('/').replace('/', os.sep)

        # Special handling for index.html if the path ends with a slash (e.g., /css/)
        if relative_path and relative_path.endswith(os.sep):
            relative_path = relative_path.rstrip(os.sep)
            file_name = "index.html"
        else:
            file_name = relative_path

    # Construct the full path to the file
    # We need to handle the case where relative_path is empty (i.e., request_path was "/")
    if relative_path == "":
        full_path = os.path.join(web_root, "index.html")
    else:
        full_path = os.path.join(web_root, file_name)

    # Security check: Ensure the resolved path is still within the web_root
    # This prevents directory traversal attacks (e.g., ../../../etc/passwd)
    absolute_web_root = os.path.abspath(web_root)
    absolute_full_path = os.path.abspath(full_path)

    if not absolute_full_path.startswith(absolute_web_root):
        return (404, b"Not Found")

    try:
        if os.path.isfile(full_path):
            with open(full_path, 'rb') as f:
                content = f.read()
            return (200, content)
        else:
            return (404, b"Not Found")
    except FileNotFoundError:
        return (404, b"Not Found")
    except Exception:
        # Catch other potential IO errors
        return (500, b"Internal Server Error")

