import re
from urllib.parse import urlparse

def is_local_redirect(target: str, host: str) -> bool:
    """
    Checks whether the redirect destination target is on the same site as the host name host.
    """

    # Check for forbidden characters first
    for char in target:
        if char == '\\' or char == ' ' or (ord(char) < 32 or ord(char) == 127):
            return False

    # Case 1: Site-relative path
    if target.startswith('/'):
        # Must start with '/', and the character immediately following that '/' (if present) must not be '/'
        if len(target) > 1 and target[1] != '/':
            return True
        # If target is just "/" or starts with "//", it's not a valid local redirect by this rule
        return False

    # Case 2: Absolute URL
    if target.startswith('http://') or target.startswith('https://'):
        try:
            result = urlparse(target)

            # Extract hostname, ignoring user info and port
            hostname = result.hostname

            if hostname and hostname.lower() == host.lower():
                return True
            else:
                return False
        except Exception:
            # Should not happen with standard URLs, but handle parsing errors defensively
            return False

    # All other cases
    return False

