from urllib.parse import urlparse

def is_allowed_webhook(url: str) -> bool:
    """
    Determines whether the string url can be registered as a webhook endpoint.
    """

    # 1. The url starts with https:// (case-insensitive).
    if not url.lower().startswith("https://"):
        return False

    # 2. The url contains no backslashes, no spaces, and no control characters (a character with a code less than 32 or equal to 127).
    if '\\' in url or ' ' in url:
        return False
    for char in url:
        code = ord(char)
        if 0 <= code <= 31 or code == 127:
            return False

    try:
        parsed_url = urlparse(url)
    except ValueError:
        return False

    # Check scheme (already partially checked, but good practice)
    if parsed_url.scheme != 'https':
        return False

    # Check for userinfo part (user@ or user:password@)
    netloc = parsed_url.netloc
    if '@' in netloc:
        # Extract host part after userinfo
        host_with_port = netloc.split('@')[-1]
    else:
        host_with_port = netloc

    # Separate host and port
    host = host_with_port
    port = None
    if ':' in host_with_port:
        try:
            host, port_str = host_with_port.rsplit(':', 1)
            port = int(port_str)
        except ValueError:
            # Malformed port, treat as invalid
            return False

    # 3. The host of url (after userinfo) is a DNS name:
    #    - it has two or more labels separated by '.'
    #    - each label is non-empty and consists only of ASCII letters, digits, and -
    #    - the last label consists only of letters
    #    - it is not 'localhost' and does not end with '.localhost' (case-insensitive)

    # Remove trailing '.' if present
    if host.endswith('.'):
        host = host[:-1]

    # Check for localhost exclusions
    if host.lower() == 'localhost' or host.lower().endswith('.localhost'):
        return False

    labels = host.split('.')
    if len(labels) < 2:
        return False

    # Check label constraints
    for i, label in enumerate(labels):
        if not label:
            return False  # Non-empty label

        # Check if label consists only of ASCII letters, digits, and -
        if not re.fullmatch(r'[a-zA-Z0-9-]+', label):
            return False

        # Check last label constraint (must consist only of letters)
        if i == len(labels) - 1:
            if not re.fullmatch(r'[a-zA-Z]+', label):
                return False

    # 4. The port is absent or is 443.
    if port is not None and port != 443:
        return False

    return True
