def is_valid_parentheses(s: str) -> bool:
    """
    Checks if the string s has valid parentheses.
    s is composed only of '(', ')', '[', ']', '{', and '}'.
    For it to be valid, every opening bracket must be closed by the same type of bracket in the correct order.
    Returns True if s is valid, False otherwise. An empty string is valid.
    """
    stack = []
    mapping = {")": "(", "]": "[", "}": "{"}

    for char in s:
        if char in "([{":
            stack.append(char)
        elif char in ")]}":
            if not stack:
                return False
            top_element = stack.pop()
            if mapping[char] != top_element:
                return False
        # Assuming the input string only contains the specified characters, 
        # no need to handle other characters.

    return not stack
