def char_frequencies(text: str) -> dict[str, int]:
    """
    Calculates the frequency of each character in the given text.

    Whitespace characters are ignored, and the case of the characters is preserved.

    Args:
        text: The input string.

    Returns:
        A dictionary where keys are characters and values are their frequencies.
    """
    frequencies: dict[str, int] = {}
    for char in text:
        if char.isspace():
            continue

        if char in frequencies:
            frequencies[char] += 1
        else:
            frequencies[char] = 1

    return frequencies
