    """
    Parses the string text into a dictionary of key-value pairs.

    The string text contains 'key=value' pairs separated by semicolons (';').
    The dictionary maps each key to its value, and both are strings.
    Whitespace around each pair, key and value is removed.
    The key is the part of a pair before its first '=', and parts that contain no '=' are ignored.
    An empty string gives an empty dictionary.

    Args:
        text: The string containing key=value pairs.

    Returns:
        A dictionary mapping keys to values.
    """
    if not text:
        return {}

    result: dict[str, str] = {}
    pairs = text.split(';')

    for pair in pairs:
        pair = pair.strip()
        if not pair:
            continue

        if '=' in pair:
            try:
                key, value = pair.split('=', 1)
                key_stripped = key.strip()
                value_stripped = value.strip()

                if key_stripped:
                    result[key_stripped] = value_stripped
            except ValueError:
                # Should not happen if '=' is checked, but good practice
