def evaluate_expression(expr: str) -> int:
    """
    Evaluates the arithmetic expression in the string expr and returns its value as an integer.

    The expression consists of non-negative integer literals, the binary operators +, -, *, /, ^,
    the unary minus -, the parentheses (, ) and spaces, which are ignored.
    The operator ^ is exponentiation: it is right-associative and binds tighter than everything else.
    The order of precedence, from the tightest to the loosest, is: ^, the unary minus, *, / , and finally +, -.
    Operators of the same level, except ^, are applied from left to right.
    The unary minus may appear at the start of the expression, after '(', or after one of the binary operators +, -, *, /.
    The operator / is integer division that truncates toward zero.
    If a division by zero occurs, the function raises ZeroDivisionError.
    The expression is always well formed.
    """
    import re

    # Tokenization: numbers, operators, parentheses
    tokens = re.findall(r'\d+|\+|\-|\*|\/|\^|\(|\)', expr)

    # Preprocessing to distinguish unary minus from binary minus
    processed_tokens = []
    is_expecting_operand = True  # True at start, after '(', or after a binary operator
    for token in tokens:
        if token == '-':
            if is_expecting_operand:
                # Unary minus: treat as part of the number or a special marker for unary negation
                # We'll use a special token for unary minus to handle precedence correctly later
                processed_tokens.append('UNARY_MINUS')
            else:
                # Binary minus
                processed_tokens.append('-')
        else:
            processed_tokens.append(token)

        # Update state for the next token
        if token in ('+', '-', '*', '/', '^', '('):
            # After an operator or opening parenthesis, we expect an operand (or unary minus)
            is_expecting_operand = True
        elif token in ('1', '2', '3', '4', '5', '6', '7', '8', '9', '0'): # Should be handled by regex, but for safety
            is_expecting_operand = False
        elif token == ')':
            # After closing parenthesis, we expect a binary operator or end of expression
            is_expecting_operand = False
        elif token == 'UNARY_MINUS':
            is_expecting_operand = True

    tokens = processed_tokens

    def apply_op(op, b, a):
        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '*':
            return a * b
        elif op == '/':
            if b == 0:
                raise ZeroDivisionError("division by zero")
            # Integer division truncating toward zero
            return int(a / b)
        elif op == '^':
            return a ** b
        return 0

    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        if op == '^':
            return 3
        if op == 'UNARY_MINUS':
            # Unary minus has higher precedence than * and /
            return 4
        return

