from datetime import datetime, timedelta

def add_business_days(start: str, n: int, holidays: list[str]) -> str:
    """
    Adds or subtracts a specified number of business days from a start date.

    Args:
        start: The starting date in "YYYY-MM-DD" format.
        n: The number of business days to add (positive) or subtract (negative).
        holidays: A list of holiday dates in "YYYY-MM-DD" format.

    Returns:
        The resulting date in "YYYY-MM-DD" format.
    """
    if n == 0:
        return start

    try:
        current_date = datetime.strptime(start, "%Y-%m-%d").date()
    except ValueError:
        raise ValueError("Invalid start date format. Must be 'YYYY-MM-DD'.")

    holiday_dates = set()
    for h_str in holidays:
        try:
            holiday_dates.add(datetime.strptime(h_str, "%Y-%m-%d").date())
        except ValueError:
            raise ValueError("Invalid holiday date format. Must be 'YYYY-MM-DD'.")

    # Helper function to check if a date is a business day
    def is_business_day(date_obj: datetime.date) -> bool:
        # Monday is 0 and Sunday is 6
        weekday = date_obj.weekday()
        if weekday >= 5:  # Saturday (5) or Sunday (6)
            return False
        if date_obj in holiday_dates:
            return False
        return True

    if n > 0:
        # Move forward
        days_to_count = n
        current_date_to_check = current_date + timedelta(days=1)
        while days_to_count > 0:
            if is_business_day(current_date_to_check):
                days_to_count -= 1
            current_date_to_check += timedelta(days=1)
        return current_date_to_check.strftime("%Y-%m-%d")
    else:
        # Move backward (n is negative)
        days_to_count = abs(n)
        current_date_to_check = current_date - timedelta(days=1)
        while days_to_count > 0:
            if is_business_day(current_date_to_check):
                days_to_count -= 1
            current_date_to_check -= timedelta(days=1)
        return current_date_to_check.strftime("%Y-%m-%d")

