def expand_template(template: str, values: dict[str, str]) -> str:
    """
    Expands placeholders in a template string using values from a dictionary.

    Placeholders are defined as:
    1. {{key}} (double braces)
    2. {key} (single braces, where the key is followed by at least one '}')

    If the key exists in values, the placeholder is replaced by the value.
    Otherwise, the placeholder remains unchanged.
    Other '{' or '}' characters are treated as literals.
    """
    result = []
    i = 0
    n = len(template)

    while i < n:
        # Check for double braces {{
        if template[i:i+2] == '{{':
            j = i + 2
            # Look for the closing '}}'
            end_brace_index = -1
            for k in range(j, n + 1):
                if k == n or template[k:k+2] != '}}':
                    # If we hit the end or not '}}', this is not a valid {{...}} structure
                    break
                if template[k:k+2] == '}}':
                    end_brace_index = k + 2
                    break

            if end_brace_index != -1:
                # Found {{key}}
                key = template[i+2:end_brace_index-2]
                if key in values:
                    result.append(values[key])
                    i = end_brace_index
                    continue
                else:
                    # Key not found, keep the original placeholder
                    result.append(template[i:end_brace_index])
                    i = end_brace_index
                    continue
            # If not found or structure is invalid, treat '{' as literal
            # Fall through to general character handling below if we can't parse it as {{...}}

        # Check for single brace {
        elif template[i] == '{':
            # Check for the specific case: '{' followed by at least one '}'
            # and not part of '{{' (which was handled above)

            # Find the next '}'
            next_close_brace = -1
            for k in range(i + 1, n):
                if template[k] == '}':
                    next_close_brace = k
                    break

            if next_close_brace != -1:
                # Potential single brace placeholder {key}

                # Check if it's part of '{{' (already handled, but good safeguard)
                if i + 1 < n and template[i+1] == '{':
                    # This should have been caught by the {{ check, but if it wasn't, 
                    # we treat it as literal for now and let the loop advance.
                    pass
                else:
                    # Found a potential single brace placeholder {key}
                    # The key is everything between '{' and the *nearest* '}'
                    key = template[i+1:next_close_brace]

                    # The rule states: "that follows its nearest '}'"
                    # We assume the key is everything up to the nearest '}'

                    if key in values:
                        result.append(values[key])
                        i = next_close_brace + 1
                        continue

