def run_bank_ops(balances: dict[str, int], ops: list[tuple]) -> tuple[dict[str, int], list[int]]:
    """
    Applies a list of bank operations to a copy of the balances dictionary.

    Args:
        balances: A dictionary mapping account names (str) to balances (int).
        ops: A list of operation tuples.

    Returns:
        A tuple containing (final_balances, failed_indices), where final_balances
        is the resulting dictionary and failed_indices is a list of 0-based indices
        of failed operations in ascending order.
    """
    current_balances = balances.copy()
    account_status = {account: False for account in balances}  # False means unfrozen
    failed_indices = []

    for i, op in enumerate(ops):
        op_type = op[0]
        success = True

        try:
            if op_type == 'deposit':
                _, account, amount = op
                if account not in current_balances or amount <= 0:
                    success = False
                elif account_status[account]:
                    success = False
                else:
                    current_balances[account] += amount

            elif op_type == 'withdraw':
                _, account, amount = op
                if account not in current_balances or amount <= 0:
                    success = False
                elif account_status[account]:
                    success = False
                elif current_balances[account] < amount:
                    success = False
                else:
                    current_balances[account] -= amount

            elif op_type == 'transfer':
                _, source, target, amount = op
                if source not in current_balances or target not in current_balances:
                    success = False
                elif amount <= 0:
                    success = False
                elif account_status[source] or account_status[target]:
                    success = False
                elif source == target:
                    success = False
                elif current_balances[source] < amount + 2:  # Amount + Fee (2)
                    success = False
                else:
                    fee = 2
                    current_balances[source] -= (amount + fee)
                    current_balances[target] += amount

            elif op_type == 'freeze':
                _, account = op
                if account not in current_balances:
                    success = False
                elif account_status[account]:
                    # Already frozen, operation succeeds but makes no change
                    pass
                else:
                    account_status[account] = True

            elif op_type == 'unfreeze':
                _, account = op
                if account not in current_balances:
                    success = False
                elif not account_status[account]:
                    # Already unfrozen, operation succeeds but makes no change
                    pass
                else:
                    account_status[account] = False

            else:
                # Operation name is none of the five above
                success = False

