def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    ip = 0
    max_instructions = 1000

    while 0 <= ip < len(program) and max_instructions > 0:
        instruction_line = program[ip].strip()
        max_instructions -= 1

        if not instruction_line:
            ip += 1
            continue

        parts = instruction_line.split()
        opcode = parts[0]

        try:
            if opcode == "PUSH":
                n = int(parts[1])
                stack.append(n)
            elif opcode == "POP":
                if not stack:
                    return None  # Stack underflow
                stack.pop()
            elif opcode == "DUP":
                if not stack:
                    return None  # Stack underflow
                stack.append(stack[-1])
            elif opcode == "SWAP":
                if len(stack) < 2:
                    return None  # Stack underflow
                a = stack.pop()
                b = stack.pop()
                stack.append(a)
                stack.append(b)
            elif opcode == "ADD":
                if len(stack) < 2:
                    return None  # Stack underflow
                b = stack.pop()
                a = stack.pop()
                stack.append(a + b)
            elif opcode == "SUB":
                if len(stack) < 2:
                    return None  # Stack underflow
                b = stack.pop()
                a = stack.pop()
                stack.append(a - b)
            elif opcode == "MUL":
                if len(stack) < 2:
                    return None  # Stack underflow
                b = stack.pop()
                a = stack.pop()
                stack.append(a * b)
            elif opcode == "JMP":
                t = int(parts[1])
                if t < 0:
                    return None  # Invalid jump target
                ip = t
                continue  # Skip ip += 1 below
            elif opcode == "JZ":
                t = int(parts[1])
                if len(stack) < 1:
                    return None  # Stack underflow
                val = stack.pop()
                if val == 0:
                    ip = t
                    continue  # Skip ip += 1 below
                else:
                    ip += 1
                    continue  # Skip ip += 1 below
            else:
                # Unknown instruction
                return None
        except IndexError:
            # Malformed instruction (e.g., PUSH without argument)
            return None
        except ValueError:
            # Type conversion error (e.g., non-integer argument)
            return None

        ip += 1

    # Check for infinite loop condition (already handled by max_instructions, but good practice)
    if max_instructions < 0 and ip < len(program):
        return None

    # If the loop terminated because ip went out of bounds, return the stack content
    return stack

