import re

def is_valid_email(s: str) -> bool:
    """
    Checks if the string s is a valid email address according to specific rules.
    The format is local@domain.
    """
    if s.count('@') != 1:
        return False

    local_part, domain_part = s.split('@')

    # --- Local Part Validation ---
    # The part 'local' consists of ASCII letters, ASCII digits and the separator characters '.', '_', and '-';
    # it starts and ends with a letter or a digit, and no two separator characters are next to each other.

    # Allowed characters in local part: letters (a-z, A-Z), digits (0-9), '.', '_', '-'
    if not re.fullmatch(r"[a-zA-Z0-9._-]+", local_part):
        return False

    # Starts and ends with a letter or a digit
    if not re.match(r"[a-zA-Z0-9]", local_part):
        return False
    if not re.search(r"[a-zA-Z0-9]$", local_part):
        return False

    # No two separator characters are next to each other.
    # Separator characters are '.', '_', '-'
    if re.search(r"[._-]{2,}", local_part):
        return False

    # Check for consecutive separators (e.g., '..', '._', '-_')
    # A more precise check for consecutive separators:
    separators = ['.', '_', '-']
    for i in range(len(local_part) - 1):
        if local_part[i] in separators and local_part[i+1] in separators:
            return False


    # --- Domain Part Validation ---
    # domain অংশে একটিমাত্র ডট (.) দিয়ে আলাদা করা কমপক্ষে দুটি লেবেল থাকে;
    # প্রতিটি লেবেল ASCII অক্ষর ও অঙ্কের একটি খালি নয় এমন ক্রম, আর শেষ লেবেলে কমপক্ষে দুটি ASCII অক্ষর থাকে, অন্য কিছু নয়.

    if '.' not in domain_part:
        return False

    domain_labels = domain_part.split('.')

    # Must have at least two labels (e.g., 'a.b')
    if len(domain_labels) < 2:
        return False

    # Check each label
    for i, label in enumerate(domain_labels):
        # Each label must be non-empty
        if not label:
            return False

        # Each label consists of ASCII letters and digits only
        if not re.fullmatch(r"[a-zA-Z0-9]+", label):
            return False

        # The last label must have at least two ASCII characters
        if i == len(domain_labels) - 1 and len(label) < 2:
            return False

    return True
